// Delivers notifications to notify-service.
//
// notify-service can intermittently return transient 5xx responses (e.g. 502
// Bad Gateway) or the connection can drop mid-flight, so a single attempt is
// not enough: those failures used to be lost and users missed notifications.
// The service deduplicates on `X-Event-Id`, so retrying the same event is
// safe. Therefore we retry transient failures (network errors and 5xx
// responses) with exponential backoff plus jitter, and only give up after all
// attempts are exhausted.

const MAX_ATTEMPTS = 4; // 1 initial attempt + 3 retries
const BASE_BACKOFF_MS = 100;
const MAX_BACKOFF_MS = 5000;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// A failure is transient when the request never reached the service (thrown
// network error or no response) or the service answered with a 5xx status
// code indicating it was temporarily unable to fulfil the request. Other
// non-2xx responses (e.g. 4xx client errors) are deterministic and must not be
// retried.
function isTransientFailure(res) {
  if (!res) return true;
  const status = typeof res.status === 'number' ? res.status : res.statusCode;
  return typeof status !== 'number' || status >= 500;
}

// Exponential backoff with full jitter. Jitter prevents a thundering herd of
// simultaneous retries when many deliveries fail at once during an outage.
function backoffMs(attempt) {
  const cap = Math.min(MAX_BACKOFF_MS, BASE_BACKOFF_MS * 2 ** attempt);
  return Math.floor(Math.random() * cap);
}

async function deliver(io, event) {
  let lastFailure;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
    try {
      const res = await io.post('/notify', event);
      if (!isTransientFailure(res)) {
        return res;
      }
      lastFailure = res;
    } catch (err) {
      lastFailure = err;
    }

    if (attempt < MAX_ATTEMPTS) {
      await sleep(backoffMs(attempt));
    }
  }

  if (lastFailure instanceof Error) {
    throw lastFailure;
  }
  const status = lastFailure && (lastFailure.status || lastFailure.statusCode);
  throw new Error(
    `notify-service delivery failed after ${MAX_ATTEMPTS} attempts` +
      (status ? ` (last status: ${status})` : '')
  );
}

module.exports = { deliver };

const { deliver } = require('/workspace/src/dispatcher.js');

async function fakeIo(statuses, mode = 'respond') {
  const calls = [];
  return {
    calls,
    async post(path, event) {
      calls.push({ path, event });
      if (mode === 'respond') {
        const s = statuses.shift();
        return { status: s };
      }
      throw new Error('ECONNRESET: socket hang up');
    },
  };
}

(async () => {
  // 1. Success on first attempt
  let io = await fakeIo([200]);
  let res = await deliver(io, { id: 1 });
  console.log('1. success first try:', res.status, 'calls =', io.calls.length, '(expect 200, 1)');

  // 2. Two 502s then success -> should retry and succeed
  io = await fakeIo([502, 502, 200]);
  const t0 = Date.now();
  res = await deliver(io, { id: 2 });
  const elapsed = Date.now() - t0;
  console.log('2. 502,502 then 200:', res.status, 'calls =', io.calls.length, 'elapsed(ms) =', elapsed, '(expect 200, 3, >0)');

  // 3. Always 502 -> should throw after MAX_ATTEMPTS
  io = await fakeIo([502, 502, 502, 502]);
  try {
    await deliver(io, { id: 3 });
    console.log('3. FAIL: expected throw');
  } catch (e) {
    console.log('3. always 502 threw:', e.message, '| calls =', io.calls.length, '(expect 4)');
  }

  // 4. Network error every time -> should retry then rethrow the error
  io = await fakeIo([], 'throw');
  try {
    await deliver(io, { id: 4 });
    console.log('4. FAIL: expected throw');
  } catch (e) {
    console.log('4. network error rethrown:', e.message, '| calls =', io.calls.length, '(expect 4)');
  }

  // 5. 400 client error -> must NOT retry
  io = await fakeIo([400]);
  res = await deliver(io, { id: 5 });
  console.log('5. 400 no retry:', res.status, 'calls =', io.calls.length, '(expect 400, 1)');

  // 6. statusCode-style responses also recognized (and 503 retried)
  io = {
    calls: [],
    async post(path, event) {
      this.calls.push(path);
      if (this.calls.length < 3) return { statusCode: 503 };
      return { statusCode: 204 };
    },
  };
  res = await deliver(io, { id: 6 });
  console.log('6. statusCode 503,503,204:', res.statusCode, 'calls =', io.calls.length, '(expect 204, 3)');
})();

